def parse_int(v, opt):
    try:
        return int(v, 10)
    except Exception:
        raise CliError(f"error: invalid value '{v}' for '{opt}': invalid digit found in string")

def parse_port(v, opt='--port <PORT>'):
    n = parse_int(v, opt)
    if n < 0 or n > 65535:
        raise CliError(f"error: invalid value '{v}' for '{opt}': invalid port number")
    return n

def parse_chmod(v):
    try:
        return int(v, 8)
    except Exception:
        raise CliError(f"error: invalid value '{v}' for '--chmod <CHMOD>': invalid digit found in string")

