            elif a == '--web-upload-files-concurrency': c.web_upload_concurrency = parse_int(val, '--web-upload-files-concurrency <WEB_UPLOAD_CONCURRENCY>')
            elif a == '--chmod': c.chmod = parse_chmod(val)
            elif a in ('--media-type','-m'): c.media_types.append(check_choice(val, '--media-type <MEDIA_TYPE>', ['image','audio','video']))
            elif a in ('--raw-media-type','-M'): c.raw_media_type = val
            elif a in ('--on-duplicate-files','-o'): c.on_duplicate = check_choice(val, '--on-duplicate-files <ON_DUPLICATE_FILES>', ['error','overwrite','rename'])
            elif a in ('--title','-t'): c.title = val
            elif a == '--header': c.headers.append(val)
            elif a == '--tls-cert': c.tls_cert = val
            elif a == '--tls-key': c.tls_key = val
            elif a == '--size-display': c.size_display = check_choice(val, '--size-display <SIZE_DISPLAY>', ['human','exact'])
            elif a == '--file-external-url': c.file_external_url = val
        elif a in FLAGS:
            if a == '--print-manpage': print_manpage(); sys.exit(0)
            setattr(c, FLAGS[a], True)
        elif a.startswith('-') and a not in ('-',):
            raise CliError(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [PATH]")
        else:
            positional.append(a)
        i += 1
    if positional:
        if len(positional) > 1:
            raise CliError(f"error: unexpected argument '{positional[1]}' found\n\nUsage: executable [OPTIONS] [PATH]")
        c.path = positional[0]
    # implications resembling clap requirements
    if c.spa and not c.index:
        raise CliError("error: the following required arguments were not provided:\n  --index <INDEX>\n\nUsage: executable --index <INDEX> --spa <PATH>")
    if c.media_types and not c.upload:
        raise CliError("error: the following required arguments were not provided:\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\n\nUsage: executable --upload-files [<ALLOWED_UPLOAD_DIR>] --media-type <MEDIA_TYPE> <PATH>")
    if c.tls_cert and not c.tls_key:
        raise CliError("error: the following required arguments were not provided:\n  --tls-key <TLS_KEY>\n\nUsage: executable --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>")
    if c.tls_key and not c.tls_cert:
        raise CliError("error: the following required arguments were not provided:\n  --tls-cert <TLS_CERT>\n\nUsage: executable --tls-key <TLS_KEY> --tls-cert <TLS_CERT> <PATH>")
    if c.auth_file:
        try:
            for line in Path(c.auth_file).read_text().splitlines():
                line = line.strip('\n')
                if line:
                    c.auth.extend(parse_auth_value(line, '--auth-file <AUTH_FILE>'))
        except CliError: raise
        except Exception as e:
            raise CliError(f"Error: Failed to read auth file\ncaused by: {e}", 1)
    return c


def print_completion(shell):
    if shell not in ('bash','elvish','fish','powershell','zsh'):
        raise CliError(f"error: invalid value '{shell}' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]")
    if shell == 'bash':
        print("_miniserve() {\n    local cur prev opts\n    COMPREPLY=()\n    cur=\"${COMP_WORDS[COMP_CWORD]}\"\n    opts=\"--help --version --port --interfaces --auth --index --spa --pretty-urls --upload-files --rm-files --enable-tar --enable-tar-gz --enable-zip\"\n    COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )\n}\ncomplete -F _miniserve miniserve")
    elif shell == 'zsh':
        print("#compdef miniserve\n_arguments '*::arg:_files' '--help[Print help]' '--version[Print version]' '--port[Port to use]' '--index[Index file]' '--upload-files[Enable uploads]'")
    else:
        print(f"# miniserve {shell} completions")

def print_manpage():
    print(f".TH miniserve 1 \"\" \"miniserve {VERSION}\"\n.SH NAME\nminiserve \\- For when you really just want to serve some files over HTTP right now!\n.SH SYNOPSIS\n.B miniserve\n[OPTIONS] [PATH]\n.SH DESCRIPTION\nFor when you really just want to serve some files over HTTP right now!\n.SH OPTIONS\nSee --help for all command line options.")


def human_size(n):
    try: n = int(n)
    except: return ''
    units = ['B','KB','MB','GB','TB','PB']
    v = float(n); u = 0
    while v >= 1000 and u < len(units)-1:
        v /= 1000.0; u += 1
    if u == 0: return f"{n} B"
    if v < 10: return f"{v:.1f} {units[u]}"
    return f"{v:.0f} {units[u]}"

def fmt_mtime(ts):
    dt = _dt.datetime.fromtimestamp(ts, _dt.timezone.utc)
    return dt.strftime('%Y-%m-%d %H:%M:%S +00:00 ')

def history(ts):
    diff = time.time() - ts
    if diff < 60: return 'now'
    if diff < 3600: return f"{int(diff//60)} minutes ago"
    if diff < 86400: return f"{int(diff//3600)} hours ago"
    return f"{int(diff//86400)} days ago"

def http_date(ts=None):
    if ts is None: ts = time.time()
    return email.utils.formatdate(ts, usegmt=True)

def etag_for(p):
    try:
        st = os.stat(p)
        raw = f"{st.st_ino}:{st.st_size}:{int(st.st_mtime)}:{int(st.st_ctime)}".encode()
        h = hashlib.md5(raw).hexdigest()[:8]
        return '"%x:%x:%x:%s"' % (st.st_ino & 0xffffffff, st.st_size, int(st.st_mtime), h)
    except Exception:
        return '"0"'

def guess_type(path):
    ctype, enc = mimetypes.guess_type(path)
    if not ctype: ctype = 'application/octet-stream'
    if ctype.startswith('text/') or ctype in ('application/javascript','application/json','image/svg+xml'):
        if 'charset=' not in ctype:
            ctype += '; charset=utf-8'
    return ctype

def safe_join(root, req_path):
    # req_path is URL path relative to route prefix and starts with '/'
    req_path = urllib.parse.unquote(req_path.split('?',1)[0])
    req_path = posixpath.normpath('/' + req_path.lstrip('/'))
    parts = [p for p in req_path.split('/') if p and p not in ('.','..')]
    candidate = os.path.abspath(os.path.join(root, *parts))
    root_abs = os.path.abspath(root)
    if candidate != root_abs and not candidate.startswith(root_abs + os.sep):
        return None
    return candidate

def is_hidden_name(name):
    return name.startswith('.')

def path_allowed_by_prefix(path, allowed, root):
    if not allowed:
        return True
    allowed_fs = safe_join(root, allowed)
    if not allowed_fs: return False
    ap = os.path.abspath(path); aa = os.path.abspath(allowed_fs)
    return ap == aa or ap.startswith(aa + os.sep)

def verify_auth(header, auths):
    if not auths:
        return True, False
    if not header or not header.startswith('Basic '):
        return False, False
    try:
        decoded = base64.b64decode(header.split(None,1)[1]).decode('utf-8')
        user, pwd = decoded.split(':',1)
    except Exception:
        return False, True
    for u, kind, val in auths:
        if u != user: continue
        if kind == 'plain' and pwd == val: return True, True
        if kind == 'sha256' and hashlib.sha256(pwd.encode()).hexdigest().lower() == val.lower(): return True, True
        if kind == 'sha512' and hashlib.sha512(pwd.encode()).hexdigest().lower() == val.lower(): return True, True
    return False, True

class Handler(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    server_version = ''
    sys_version = ''

    def log_message(self, fmt, *args):
        pass

    def setup(self):
        super().setup()
        self._started = time.time(); self._status = 0; self._bytes = 0

    def finish(self):
        try: super().finish()
        finally:
            cfg = self.server.config
            if cfg.verbose and self._status:
                ua = self.headers.get('User-Agent','-')
                ref = self.headers.get('Referer','-')
                dur = max(0, time.time() - getattr(self, '_started', time.time()))
                log('INFO', f'{self.client_address[0]} "{self.command} {self.path} {self.request_version}" {self._status} {self._bytes} "{ref}" "{ua}" {dur:.6f}')

    def send_basic(self, status, body=b'', ctype=None, headers=None, head=False):
        self._status = status; self._bytes = len(body)
        self.send_response_only(status)
        if ctype: self.send_header('content-type', ctype)
        self.send_header('content-length', str(len(body)))
        if headers:
            for k,v in headers:
                self.send_header(k, v)
        for h in self.server.config.headers:
            if ':' in h:
                k,v = h.split(':',1); self.send_header(k.strip(), v.strip())
        self.send_header('date', http_date())
        self.end_headers()
        if not head and body:
            self.wfile.write(body)

    def send_redirect(self, loc, status=307):
        phrase = {303:'See Other',307:'Temporary Redirect'}.get(status,'Temporary Redirect')
        self._status = status; self._bytes = 0
        self.send_response_only(status, phrase)
        self.send_header('content-length','0')
        self.send_header('location', loc)
        self.send_header('date', http_date())
        self.end_headers()

    def do_HEAD(self): self.handle_request(head=True)
    def do_GET(self): self.handle_request(head=False)
    def do_OPTIONS(self):
        self.send_basic(200, b'', headers=[('allow','GET, HEAD, POST, OPTIONS, PROPFIND')], head=True)
    def do_PROPFIND(self):
        if not self.server.config.enable_webdav:
            return self.error_page(405, 'Method Not Allowed', 'Method not allowed')
        return self.webdav_propfind()
    def do_POST(self): self.handle_post()

    def check_auth(self):
        ok, had = verify_auth(self.headers.get('Authorization'), self.server.config.auth)
        if ok: return True
        if not had:
            self.send_basic(401, b'', headers=[('www-authenticate','Basic')])
        else:
            body = self.error_html(401, 'Unauthorized', 'Unauthorized')
            self.send_basic(401, body, 'text/html', headers=[('www-authenticate','Basic realm="miniserve"')])
        return False

    def strip_prefix(self):
        cfg = self.server.config
        parsed = urllib.parse.urlsplit(self.path)
        path = parsed.path
        rp = cfg.route_prefix
        if rp:
            if path == rp:
                self.send_redirect(rp + '/')
                return None, None
            if not (path == rp + '/' or path.startswith(rp + '/')):
                return False, parsed
            path = path[len(rp):] or '/'
        return path, parsed

    def handle_request(self, head=False):
        cfg = self.server.config
        sp, parsed = self.strip_prefix()
        if sp is None: return
        if sp is False:
            return self.error_page(404, 'Not Found', f'Route {urllib.parse.urlsplit(self.path).path} could not be found', head=head)
        # Internal resources are public in original only after auth? keep behind auth for normal pages
        if sp.startswith('/__miniserve_internal/'):
            return self.internal(sp, head)
        if not self.check_auth(): return
        root = self.server.root
        # single file mode
        if os.path.isfile(root):
            if sp in ('','/'):
                return self.serve_file(root, head=head)
            return self.error_page(404, 'Not Found', f'Route {sp} could not be found', head=head)
        if parsed.query:
            q = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
            if 'download' in q and sp.endswith('/'):
                val = q.get('download',[''])[0]
                target = safe_join(root, sp)
                if target and os.path.isdir(target):
                    if val == 'tar' and cfg.enable_tar: return self.serve_archive(target, 'tar', head)
                    if val == 'tar_gz' and cfg.enable_tar_gz: return self.serve_archive(target, 'tar_gz', head)
                    if val == 'zip' and cfg.enable_zip: return self.serve_archive(target, 'zip', head)
        fs = safe_join(root, sp)
        if not fs:
            return self.error_page(404, 'Not Found', f'Route {sp} could not be found', head=head)
        if cfg.no_symlinks and os.path.islink(fs):
            return self.error_page(404, 'Not Found', 'File not found.', head=head)
        if not cfg.hidden and any(part.startswith('.') for part in Path(sp).parts if part not in ('/','')):
            return self.error_page(404, 'Not Found', 'File not found.', head=head)
        if os.path.isdir(fs):
            if not sp.endswith('/'):
                loc = (cfg.route_prefix + sp + '/') if cfg.route_prefix else sp + '/'
                return self.send_redirect(loc)
            if cfg.index:
                idx = os.path.join(fs, cfg.index)
                if os.path.isfile(idx):
                    return self.serve_file(idx, head=head, display_name=cfg.index)
            if cfg.disable_indexing:
                return self.error_page(404, 'Not Found', 'File not found.', head=head)
            return self.serve_listing(fs, sp, parsed, head)
        if os.path.isfile(fs):
            return self.serve_file(fs, head=head)
        if cfg.pretty_urls and not sp.endswith('/'):
            p2 = safe_join(root, sp + '.html')
            if p2 and os.path.isfile(p2): return self.serve_file(p2, head=head)
        if cfg.spa and cfg.index:
            idx = os.path.join(root, cfg.index)
            if os.path.isfile(idx): return self.serve_file(idx, head=head, display_name=cfg.index)
        return self.error_page(404, 'Not Found', f'Route {sp} could not be found', head=head)

    def internal(self, sp, head=False):
        if sp.endswith('/style.css'):
            return self.send_basic(200, STYLE_CSS.encode(), 'text/css; charset=utf-8', head=head)
        if sp.endswith('/favicon.svg'):
            logo_path = Path(__file__).with_name('data').joinpath('logo.svg')
            data = logo_path.read_bytes() if logo_path.exists() else LOGO_SVG.encode()
            return self.send_basic(200, data, 'image/svg+xml; charset=utf-8', head=head)
        if sp.endswith('/api') and self.command == 'POST':
            return self.handle_api()
        return self.error_page(404, 'Not Found', f'Route {sp} could not be found', head=head)

    def handle_post(self):
        cfg = self.server.config
        sp, parsed = self.strip_prefix()
        if sp is None: return
        if sp is False: return self.error_page(404,'Not Found',f'Route {urllib.parse.urlsplit(self.path).path} could not be found')
        if sp.startswith('/__miniserve_internal/api'):
            return self.handle_api()
        if not self.check_auth(): return
        if sp == '/upload' and cfg.upload:
            return self.handle_upload(parsed)
        if sp == '/rm' and cfg.rm:
            return self.handle_rm(parsed)
        if sp == '/mkdir' and cfg.mkdir:
            return self.handle_mkdir(parsed)
        return self.error_page(404, 'Not Found', f'Route {sp} could not be found')

    def handle_api(self):
        length = int(self.headers.get('content-length','0') or 0)
        data = self.rfile.read(length) if length else b''
        try: obj = json.loads(data.decode() or '{}')
        except Exception: obj = {}
        if isinstance(obj, dict) and 'DirSize' in obj:
            sp = obj['DirSize']
            target = safe_join(self.server.root, sp)
            total = 0
            if target and os.path.isdir(target):
                for dirpath, dirs, files in os.walk(target):
                    for f in files:
                        try: total += os.path.getsize(os.path.join(dirpath,f))
                        except OSError: pass
                return self.send_basic(200, human_size(total).encode(), 'text/plain; charset=utf-8')
        return self.send_basic(400, b'Bad request', 'text/plain; charset=utf-8')

    def handle_upload(self, parsed):
        cfg = self.server.config
        q = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        rel = q.get('path', ['/'])[0] or '/'
        target_dir = safe_join(self.server.root, rel)
        if not target_dir or not os.path.isdir(target_dir) or not path_allowed_by_prefix(target_dir, cfg.upload_dir, self.server.root):
            return self.send_basic(403, b'Forbidden', 'text/plain; charset=utf-8')
        ctype, pdict = cgi.parse_header(self.headers.get('content-type',''))
        if ctype != 'multipart/form-data':
            return self.send_basic(400, b'Expected multipart/form-data', 'text/plain; charset=utf-8')
        fs = cgi.FieldStorage(fp=self.rfile, headers=self.headers, environ={'REQUEST_METHOD':'POST','CONTENT_TYPE':self.headers.get('content-type',''),'CONTENT_LENGTH':self.headers.get('content-length','0')}, keep_blank_values=True)
        fields = []
        if isinstance(fs.list, list): fields = fs.list
        saved = 0
        for field in fields:
            if not getattr(field, 'filename', None): continue
            name = os.path.basename(field.filename)
            if not name: continue
            # media type filtering
            if cfg.media_types:
                mt = (field.type or '').split('/')[0]
                if mt not in cfg.media_types:
                    return self.send_basic(415, b'Unsupported Media Type', 'text/plain; charset=utf-8')
            dest = os.path.join(target_dir, name)
            if os.path.exists(dest):
                if cfg.on_duplicate == 'error':
                    msg = b'File already exists, and the on_duplicate_files option is set to error out'
                    return self.send_basic(409, msg, 'text/plain; charset=utf-8')
                if cfg.on_duplicate == 'rename':
                    base, ext = os.path.splitext(name); n = 1
                    while os.path.exists(dest):
                        dest = os.path.join(target_dir, f"{base}-{n}{ext}"); n += 1
            tmpdir = cfg.temp_directory or tempfile.gettempdir()
            fd, tmp = tempfile.mkstemp(dir=tmpdir)
            with os.fdopen(fd,'wb') as out:
                shutil.copyfileobj(field.file, out)
            shutil.move(tmp, dest)
            if cfg.chmod is not None:
                os.chmod(dest, cfg.chmod)
            saved += 1
        if saved == 0:
            return self.send_basic(400, b'No file uploaded', 'text/plain; charset=utf-8')
        loc = self.server.config.route_prefix + (rel if rel.endswith('/') else rel + '/')
        if not loc: loc = '/'
        return self.send_redirect(loc, 303)

    def handle_rm(self, parsed):
        cfg = self.server.config
        q = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        rel = q.get('path', [''])[0]
        target = safe_join(self.server.root, rel)
        if not target or not path_allowed_by_prefix(target, cfg.rm_dir, self.server.root) or os.path.abspath(target) == os.path.abspath(self.server.root):
            return self.send_basic(403, b'Forbidden', 'text/plain; charset=utf-8')
        try:
            if os.path.isdir(target) and not os.path.islink(target): shutil.rmtree(target)
            else: os.unlink(target)
        except FileNotFoundError:
            pass
        except Exception as e:
            return self.send_basic(500, str(e).encode(), 'text/plain; charset=utf-8')
        parent = posixpath.dirname('/' + rel.strip('/'))
        if not parent.endswith('/'): parent += '/'
        loc = self.server.config.route_prefix + (parent or '/')
        return self.send_redirect(loc, 303)

    def handle_mkdir(self, parsed):
        q = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        rel = q.get('path',[''])[0] or q.get('name',[''])[0]
        target = safe_join(self.server.root, rel)
        if not target: return self.send_basic(403, b'Forbidden', 'text/plain; charset=utf-8')
        try: os.makedirs(target, exist_ok=True)
        except Exception as e: return self.send_basic(500, str(e).encode(), 'text/plain; charset=utf-8')
        parent = posixpath.dirname('/' + rel.strip('/'))
        if not parent.endswith('/'): parent += '/'
        return self.send_redirect(self.server.config.route_prefix + (parent or '/'), 303)

    def serve_file(self, path, head=False, display_name=None):
        try:
            st = os.stat(path)
            size = st.st_size
            ctype = guess_type(path)
            et = etag_for(path)
            # conditional etag/date
            if self.headers.get('If-None-Match') == et:
                self._status = 304; self._bytes = 0
                self.send_response_only(304, 'Not Modified')
                self.send_header('etag', et); self.send_header('date', http_date()); self.end_headers(); return
            start, end = 0, size-1; status = 200
            rng = self.headers.get('Range')
            if rng and rng.startswith('bytes='):
                spec = rng[6:].split(',',1)[0]
                try:
                    if spec.startswith('-'):
                        n = int(spec[1:]); start = max(0, size-n)
                    else:
                        a,b = spec.split('-',1); start = int(a); end = int(b) if b else size-1
                    if start < 0 or end < start or start >= size: raise ValueError
                    end = min(end, size-1); status = 206
                except Exception:
                    return self.send_basic(416, b'', headers=[('content-range', f'bytes */{size}')], head=head)
            length = max(0, end-start+1) if size else 0
            headers = [('accept-ranges','bytes'), ('content-type', ctype), ('etag', et), ('last-modified', http_date(st.st_mtime)), ('content-disposition', f'inline; filename="{display_name or os.path.basename(path)}"')]
            if status == 206:
                headers.insert(-1, ('content-range', f'bytes {start}-{end}/{size}'))
            self._status = status; self._bytes = length
            self.send_response_only(status)
            self.send_header('content-length', str(length))
            for k,v in headers: self.send_header(k,v)
            for h in self.server.config.headers:
                if ':' in h:
                    k,v = h.split(':',1); self.send_header(k.strip(), v.strip())
            self.send_header('date', http_date())
            self.end_headers()
            if not head and length:
                with open(path,'rb') as f:
                    f.seek(start)
                    remaining = length
                    while remaining:
                        chunk = f.read(min(65536, remaining))
                        if not chunk: break
                        self.wfile.write(chunk); remaining -= len(chunk)
        except OSError:
            return self.error_page(404, 'Not Found', 'File not found.', head=head)

    def list_entries(self, fs, web_path, parsed):
        cfg = self.server.config
        entries = []
        try: names = os.listdir(fs)
        except OSError: return []
        for name in names:
            if not cfg.hidden and is_hidden_name(name): continue
            p = os.path.join(fs, name)
            if cfg.no_symlinks and os.path.islink(p): continue
            try: st = os.stat(p)
            except OSError: continue
            isdir = os.path.isdir(p)
            entries.append((name,p,st,isdir,os.path.islink(p)))
        q = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        method = q.get('sort',[cfg.sort_method])[0]
        order = q.get('order',['asc'])[0]
        def key(e):
            name,p,st,isdir,isl = e
            if method == 'size': return (0 if isdir else st.st_size, name.lower())
            if method == 'date': return (st.st_mtime, name.lower())
            return name.lower()
        entries.sort(key=key, reverse=(order=='desc'))
        if cfg.dirs_first:
            entries.sort(key=lambda e: not e[3])
        return entries

    def serve_listing(self, fs, web_path, parsed, head=False):
        cfg = self.server.config
        body = self.make_listing_html(fs, web_path, parsed).encode('utf-8')
        return self.send_basic(200, body, 'text/html; charset=utf-8', head=head)

    def make_listing_html(self, fs, web_path, parsed):
        cfg = self.server.config
        prefix = cfg.route_prefix
        host_title = cfg.title or self.headers.get('Host','')
        display_path = urllib.parse.unquote(web_path)
        title = html.escape(host_title)
        internal = prefix + '/__miniserve_internal'
        parts = ['<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light">',
