                f'<body><div class="error"><p>{status} {short}</p><p>{html.escape(message)}</p>{back}{footer}</div></body></html>').encode('utf-8')

    def error_page(self, status, short, message, head=False):
        body = self.error_html(status, short, message)
        if status == 404:
            log('ERROR', message)
        return self.send_basic(status, body, 'text/html', head=head)

    def serve_archive(self, target, kind, head=False):
        base = os.path.basename(os.path.abspath(target)) or 'archive'
        buf = io.BytesIO()
        if kind in ('tar','tar_gz'):
            mode = 'w:gz' if kind == 'tar_gz' else 'w'
            with tarfile.open(fileobj=buf, mode=mode) as tf:
                tf.add(target, arcname=base, recursive=True)
            ext = 'tar.gz' if kind == 'tar_gz' else 'tar'
            ctype = 'application/gzip' if kind == 'tar_gz' else 'application/tar'
        else:
            with zipfile.ZipFile(buf, 'w', zipfile.ZIP_STORED) as zf:
                for dirpath, dirs, files in os.walk(target):
                    rel_dir = os.path.relpath(dirpath, os.path.dirname(target))
                    if not files:
                        zf.writestr(rel_dir.rstrip('/') + '/', b'')
                    for f in files:
                        p = os.path.join(dirpath, f)
                        zf.write(p, os.path.relpath(p, os.path.dirname(target)))
            ext = 'zip'; ctype = 'application/zip'
        data = buf.getvalue()
        return self.send_basic(200, data, ctype, headers=[('content-transfer-encoding','binary'),('content-disposition',f'attachment; filename="{base}.{ext}"')], head=head)

    def webdav_propfind(self):
        sp, parsed = self.strip_prefix()
        if sp is None or sp is False: return self.error_page(404,'Not Found','File not found.')
        if not self.check_auth(): return
        fs = safe_join(self.server.root, sp)
        if not fs or not os.path.exists(fs): return self.error_page(404,'Not Found','File not found.')
        host = self.headers.get('Host','')
        href = (self.server.config.route_prefix + sp)
        body = f'''<?xml version="1.0" encoding="utf-8"?><D:multistatus xmlns:D="DAV:"><D:response><D:href>{html.escape(href)}</D:href><D:propstat><D:prop><D:displayname>{html.escape(os.path.basename(fs) or '/')}</D:displayname><D:getcontentlength>{os.path.getsize(fs) if os.path.isfile(fs) else 0}</D:getcontentlength></D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat></D:response></D:multistatus>'''.encode()
        return self.send_basic(207, body, 'application/xml; charset=utf-8')

class DualStackServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def validate_and_run(c):
    global CONFIG; CONFIG = c
    if not c.path:
        # original prompts on a TTY; benchmark runs non-interactively, reproduce that path.
        print(f"miniserve v{VERSION}")
        log('ERROR', 'Refusing to start as no explicit serve path was set and no interactive terminal was attached')
        log('ERROR', 'Please set an explicit serve path like: `miniserve /my/path`')
        print('Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached', file=sys.stderr)
        print('Please set an explicit serve path like: `miniserve /my/path`', file=sys.stderr)
        sys.exit(1)
    try:
        root = os.path.realpath(c.path)
    except Exception:
        root = c.path
    if not os.path.exists(root):
        log('ERROR', 'Failed to resolve path to be served')
        log('ERROR', 'caused by: No such file or directory (os error 2)')
        print('Error: Failed to resolve path to be served', file=sys.stderr)
        print('caused by: No such file or directory (os error 2)', file=sys.stderr)
        sys.exit(1)
    if c.random_route:
        c.route_prefix = '/' + ''.join(random.choice('0123456789abcdef') for _ in range(6))
    iface = c.interfaces[-1] if c.interfaces else '0.0.0.0'
    try:
        srv = DualStackServer((iface, c.port), Handler)
    except OSError as e:
        print(f"miniserve v{VERSION}")
        addr = f"{iface}:{c.port}"
        log('ERROR', f'Failed to bind server to {addr}')
        log('ERROR', f'caused by: {e.strerror} (os error {e.errno})')
        print(f'Error: Failed to bind server to {addr}', file=sys.stderr)
        print(f'caused by: {e.strerror} (os error {e.errno})', file=sys.stderr)
        sys.exit(1)
    srv.config = c; srv.root = root
    if c.tls_cert and c.tls_key:
        try:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
            ctx.load_cert_chain(c.tls_cert, c.tls_key)
            srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
        except Exception as e:
            log('ERROR', f'Failed to set up TLS: {e}')
            print(f'Error: Failed to set up TLS: {e}', file=sys.stderr); sys.exit(1)
    actual_port = srv.server_address[1]
    scheme = 'https' if c.tls_cert else 'http'
    print(f"miniserve v{VERSION}")
    if c.verbose:
        log('INFO', 'starting 20 workers')
    # Startup text intentionally mirrors the common default even though this implementation binds one socket.
    if iface in ('0.0.0.0','::') and not c.interfaces:
        print(f"Bound to [::]:{actual_port}, 0.0.0.0:{actual_port}")
    else:
        print(f"Bound to {iface}:{actual_port}")
    print(f"Serving path {root}")
    print("Available at (non-exhaustive list):")
    rp = c.route_prefix
    print(f"    {scheme}://127.0.0.1:{actual_port}{rp}")
    try:
        hostname = socket.gethostname(); ip = socket.gethostbyname(hostname)
        if ip != '127.0.0.1': print(f"    {scheme}://{ip}:{actual_port}{rp}")
    except Exception: pass
    if iface in ('0.0.0.0','::') and not c.interfaces:
        print(f"    {scheme}://[::1]:{actual_port}{rp}")
    print('', flush=True)
    if c.verbose:
        log('INFO', 'Actix runtime found; starting in Actix runtime')
        log('INFO', f'starting service: "actix-web-service-{iface}:{actual_port}", workers: 20, listening on: {iface}:{actual_port}')
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass


def main():
    try:
        c = parse_args(sys.argv[1:])
        validate_and_run(c)
    except CliError as e:
        print_cli_error(str(e))
        sys.exit(e.code)

if __name__ == '__main__':
    main()
