    if shell=='bash': print('_miniserve() {\n    local cur opts\n    COMPREPLY=()\n    cur="${COMP_WORDS[COMP_CWORD]}"\n    opts="--help --version --port --interfaces --auth --index --spa --pretty-urls --upload-files --rm-files --enable-tar --enable-tar-gz --enable-zip"\n    COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )\n}\ncomplete -F _miniserve miniserve')
    elif shell=='zsh': print('#compdef miniserve\n_arguments "*::arg:_files" "--help[Print help]" "--version[Print version]" "--port[Port to use]"')
    else: print(f'# miniserve {shell} completions')
