def parse_args(argv):
    c=Config(); get_env_config(c); pos=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a=='--': pos.extend(argv[i+1:]); break
        if a in ('--help','-h'): sys.stdout.write(HELP_LONG if a=='--help' else HELP_SHORT); sys.exit(0)
        if a in ('--version','-V'): print(f'miniserve {VERSION}'); sys.exit(0)
        if a.startswith('--') and '=' in a:
            opt,val=a.split('=',1); argv=argv[:i]+[opt,val]+argv[i+1:]; a=opt
        if a in ('--upload-files','-u'):
            c.upload=True
            if i+1<len(argv) and argv[i+1] != '--' and not argv[i+1].startswith('-'): c.upload_dir=argv[i+1]; i+=1
            i+=1; continue
        if a in ('--rm-files','-R'):
            c.rm=True
            if i+1<len(argv) and argv[i+1] != '--' and not argv[i+1].startswith('-'): c.rm_dir=argv[i+1]; i+=1
            i+=1; continue
        if a in REQ:
            val=need(argv,i,a,REQ[a]); i+=1
            if a=='--print-completions': print_completion(val); sys.exit(0)
            elif a=='--temp-directory': c.temp_directory=val
            elif a=='--index': c.index=val
            elif a in ('--port','-p'): c.port=parse_port(val)
            elif a in ('--interfaces','-i'): c.interfaces.append(val)
            elif a in ('--auth','-a'): c.auth.extend(parse_auth_value(val))
            elif a=='--auth-file': c.auth_file=val
            elif a=='--route-prefix': c.route_prefix=norm_prefix(val)
            elif a in ('--default-sorting-method','-S'): c.sort_method=check_choice(val,'--default-sorting-method <DEFAULT_SORTING_METHOD>',['name','size','date'])
            elif a in ('--default-sorting-order','-O'): c.sort_order=check_choice(val,'--default-sorting-order <DEFAULT_SORTING_ORDER>',['asc','desc'])
            elif a in ('--color-scheme','-c'): c.color_scheme=check_choice(val,'--color-scheme <COLOR_SCHEME>',['squirrel','archlinux','zenburn','monokai'])
            elif a in ('--color-scheme-dark','-d'): c.color_scheme_dark=check_choice(val,'--color-scheme-dark <COLOR_SCHEME_DARK>',['squirrel','archlinux','zenburn','monokai'])
            elif a=='--web-upload-files-concurrency': c.web_upload_concurrency=parse_int(val,'--web-upload-files-concurrency <WEB_UPLOAD_CONCURRENCY>')
            elif a=='--chmod': c.chmod=parse_chmod(val)
            elif a in ('--media-type','-m'): c.media_types.append(check_choice(val,'--media-type <MEDIA_TYPE>',['image','audio','video']))
            elif a in ('--raw-media-type','-M'): c.raw_media_type=val
            elif a in ('--on-duplicate-files','-o'): c.on_duplicate=check_choice(val,'--on-duplicate-files <ON_DUPLICATE_FILES>',['error','overwrite','rename'])
            elif a in ('--title','-t'): c.title=val
            elif a=='--header': c.headers.append(val)
            elif a=='--tls-cert': c.tls_cert=val
            elif a=='--tls-key': c.tls_key=val
            elif a=='--size-display': c.size_display=check_choice(val,'--size-display <SIZE_DISPLAY>',['human','exact'])
            elif a=='--file-external-url': c.file_external_url=val
        elif a in FLAGS:
            if a=='--print-manpage': print_manpage(); sys.exit(0)
            setattr(c,FLAGS[a],True)
        elif a.startswith('-') and a!='-': raise CliError(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [PATH]")
        else: pos.append(a)
        i+=1
    if pos:
        if len(pos)>1: raise CliError(f"error: unexpected argument '{pos[1]}' found\n\nUsage: executable [OPTIONS] [PATH]")
        c.path=pos[0]
    if c.spa and not c.index: raise CliError('error: the following required arguments were not provided:\n  --index <INDEX>\n\nUsage: executable --index <INDEX> --spa <PATH>')
    if c.media_types and not c.upload: raise CliError('error: the following required arguments were not provided:\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\n\nUsage: executable --upload-files [<ALLOWED_UPLOAD_DIR>] --media-type <MEDIA_TYPE> <PATH>')
    if c.tls_cert and not c.tls_key: raise CliError('error: the following required arguments were not provided:\n  --tls-key <TLS_KEY>\n\nUsage: executable --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>')
    if c.tls_key and not c.tls_cert: raise CliError('error: the following required arguments were not provided:\n  --tls-cert <TLS_CERT>\n\nUsage: executable --tls-key <TLS_KEY> --tls-cert <TLS_CERT> <PATH>')
    if c.auth_file:
        for line in Path(c.auth_file).read_text().splitlines():
