def human_size(n):
    n=int(n); units=['B','KB','MB','GB','TB']; v=float(n); u=0
    while v>=1000 and u<len(units)-1: v/=1000; u+=1
    if u==0: return f'{n} B'
    return (f'{v:.1f} {units[u]}' if v<10 else f'{v:.0f} {units[u]}')
def fmt_mtime(ts): return _dt.datetime.fromtimestamp(ts,_dt.timezone.utc).strftime('%Y-%m-%d %H:%M:%S +00:00 ')
def history(ts):
    d=time.time()-ts
    if d<60: return 'now'
    if d<3600: return f'{int(d//60)} minutes ago'
    if d<86400: return f'{int(d//3600)} hours ago'
    return f'{int(d//86400)} days ago'
def http_date(ts=None): return email.utils.formatdate(time.time() if ts is None else ts, usegmt=True)
def guess_type(path):
    ctype,_=mimetypes.guess_type(path)
