def safe_join(root, req_path):
    req_path=urllib.parse.unquote(req_path.split('?',1)[0]); req_path=posixpath.normpath('/'+req_path.lstrip('/'))
    parts=[p for p in req_path.split('/') if p and p not in ('.','..')]
    cand=os.path.abspath(os.path.join(root,*parts)); root_abs=os.path.abspath(root)
    return cand if cand==root_abs or cand.startswith(root_abs+os.sep) else None
def path_allowed(path, allowed, root):
    if not allowed: return True
    af=safe_join(root,allowed)
    if not af: return False
    ap=os.path.abspath(path); aa=os.path.abspath(af)
    return ap==aa or ap.startswith(aa+os.sep)
def verify_auth(header, auths):
    if not auths: return True,False
    if not header or not header.startswith('Basic '): return False,False
    try: user,pwd=base64.b64decode(header.split(None,1)[1]).decode().split(':',1)
    except Exception: return False,True
    for u,k,v in auths:
        if u!=user: continue
        if k=='plain' and pwd==v: return True,True
        if k=='sha256' and hashlib.sha256(pwd.encode()).hexdigest().lower()==v.lower(): return True,True
        if k=='sha512' and hashlib.sha512(pwd.encode()).hexdigest().lower()==v.lower(): return True,True
    return False,True

