        if sp.startswith('/__miniserve_internal/api'): return self.handle_api()
        if not self.check_auth(): return
        if sp=='/upload' and cfg.upload: return self.handle_upload(parsed)
        if sp=='/rm' and cfg.rm: return self.handle_rm(parsed)
        if sp=='/mkdir' and cfg.mkdir: return self.handle_mkdir(parsed)
        return self.error_page(404,'Not Found',f'Route {sp} could not be found')
