def human_size(n):
    n=int(n); units=['B','KB','MB','GB','TB']; v=float(n); u=0
    while v>=1000 and u<len(units)-1: v/=1000; u+=1
    if u==0: return f'{n} B'
    return (f'{v:.1f} {units[u]}' if v<10 else f'{v:.0f} {units[u]}')
def fmt_mtime(ts): return _dt.datetime.fromtimestamp(ts,_dt.timezone.utc).strftime('%Y-%m-%d %H:%M:%S +00:00 ')
def history(ts):
    d=time.time()-ts
    if d<60: return 'now'
    if d<3600: return f'{int(d//60)} minutes ago'
    if d<86400: return f'{int(d//3600)} hours ago'
    return f'{int(d//86400)} days ago'
def http_date(ts=None): return email.utils.formatdate(time.time() if ts is None else ts, usegmt=True)
def guess_type(path):
    ctype,_=mimetypes.guess_type(path)
    ctype=ctype or 'application/octet-stream'
    if (ctype.startswith('text/') or ctype in ('application/javascript','application/json','image/svg+xml')) and 'charset=' not in ctype: ctype+='; charset=utf-8'
    return ctype
def etag_for(p):
    try:
        st=os.stat(p); raw=f'{st.st_ino}:{st.st_size}:{int(st.st_mtime)}:{int(st.st_ctime)}'.encode(); h=hashlib.md5(raw).hexdigest()[:8]
        return '"%x:%x:%x:%s"'%(st.st_ino & 0xffffffff,st.st_size,int(st.st_mtime),h)
    except Exception: return '"0"'
def safe_join(root, req_path):
    req_path=urllib.parse.unquote(req_path.split('?',1)[0]); req_path=posixpath.normpath('/'+req_path.lstrip('/'))
    parts=[p for p in req_path.split('/') if p and p not in ('.','..')]
    cand=os.path.abspath(os.path.join(root,*parts)); root_abs=os.path.abspath(root)
    return cand if cand==root_abs or cand.startswith(root_abs+os.sep) else None
def path_allowed(path, allowed, root):
    if not allowed: return True
    af=safe_join(root,allowed)
    if not af: return False
    ap=os.path.abspath(path); aa=os.path.abspath(af)
    return ap==aa or ap.startswith(aa+os.sep)
def verify_auth(header, auths):
    if not auths: return True,False
    if not header or not header.startswith('Basic '): return False,False
    try: user,pwd=base64.b64decode(header.split(None,1)[1]).decode().split(':',1)
    except Exception: return False,True
    for u,k,v in auths:
        if u!=user: continue
        if k=='plain' and pwd==v: return True,True
        if k=='sha256' and hashlib.sha256(pwd.encode()).hexdigest().lower()==v.lower(): return True,True
        if k=='sha512' and hashlib.sha512(pwd.encode()).hexdigest().lower()==v.lower(): return True,True
    return False,True

class Handler(BaseHTTPRequestHandler):
