    def finish(self):
        try: super().finish()
        finally:
            cfg=self.server.config
            if cfg.verbose and self._status:
                log('INFO',f'{self.client_address[0]} "{self.command} {self.path} {self.request_version}" {self._status} {self._bytes} "{self.headers.get("Referer","-")}" "{self.headers.get("User-Agent","-")}" {max(0,time.time()-self._started):.6f}')
    def send_basic(self,status,body=b'',ctype=None,headers=None,head=False):
        self._status=status; self._bytes=len(body); self.send_response_only(status)
        if ctype: self.send_header('content-type',ctype)
