        ok,had=verify_auth(self.headers.get('Authorization'),self.server.config.auth)
        if ok: return True
        if not had: self.send_basic(401,b'',headers=[('www-authenticate','Basic')])
        else: self.send_basic(401,self.error_html(401,'Unauthorized','Unauthorized'),'text/html',headers=[('www-authenticate','Basic realm="miniserve"')])
