            path=path[len(rp):] or '/'
        return path,parsed
    def handle_request(self,head=False):
        cfg=self.server.config; sp,parsed=self.strip_prefix()
        if sp is None: return
        if sp is False: return self.error_page(404,'Not Found',f'Route {urllib.parse.urlsplit(self.path).path} could not be found',head)
        if sp.startswith('/__miniserve_internal/'): return self.internal(sp,head)
        if not self.check_auth(): return
        root=self.server.root
        if os.path.isfile(root):
            if sp in ('','/'): return self.serve_file(root,head)
            return self.error_page(404,'Not Found',f'Route {sp} could not be found',head)
        q=urllib.parse.parse_qs(parsed.query,keep_blank_values=True)
        if 'download' in q and sp.endswith('/'):
