                if val=='tar' and cfg.enable_tar: return self.serve_archive(target,'tar',head)
                if val=='tar_gz' and cfg.enable_tar_gz: return self.serve_archive(target,'tar_gz',head)
                if val=='zip' and cfg.enable_zip: return self.serve_archive(target,'zip',head)
        fs=safe_join(root,sp)
        if not fs: return self.error_page(404,'Not Found',f'Route {sp} could not be found',head)
        if cfg.no_symlinks and os.path.islink(fs): return self.error_page(404,'Not Found','File not found.',head)
        if not cfg.hidden and any(part.startswith('.') for part in Path(sp).parts if part not in ('/','')): return self.error_page(404,'Not Found','File not found.',head)
        if os.path.isdir(fs):
            if not sp.endswith('/'):
