            if p2 and os.path.isfile(p2): return self.serve_file(p2,head)
        if cfg.spa and cfg.index:
            idx=os.path.join(root,cfg.index)
            if os.path.isfile(idx): return self.serve_file(idx,head,cfg.index)
        return self.error_page(404,'Not Found',f'Route {sp} could not be found',head)
    def internal(self,sp,head=False):
        if sp.endswith('/style.css'): return self.send_basic(200,STYLE_CSS.encode(),'text/css; charset=utf-8',head=head)
        if sp.endswith('/favicon.svg'):
            lp=BASE_DIR/'data'/'logo.svg'; data=lp.read_bytes() if lp.exists() else LOGO_SVG.encode()
            return self.send_basic(200,data,'image/svg+xml; charset=utf-8',head=head)
        if sp.endswith('/api') and self.command=='POST': return self.handle_api()
        return self.error_page(404,'Not Found',f'Route {sp} could not be found',head)
    def handle_post(self):
        cfg=self.server.config; sp,parsed=self.strip_prefix()
        if sp is None: return
        if sp is False: return self.error_page(404,'Not Found',f'Route {urllib.parse.urlsplit(self.path).path} could not be found')
        if sp.startswith('/__miniserve_internal/api'): return self.handle_api()
        if not self.check_auth(): return
        if sp=='/upload' and cfg.upload: return self.handle_upload(parsed)
        if sp=='/rm' and cfg.rm: return self.handle_rm(parsed)
        if sp=='/mkdir' and cfg.mkdir: return self.handle_mkdir(parsed)
        return self.error_page(404,'Not Found',f'Route {sp} could not be found')
    def handle_api(self):
        length=int(self.headers.get('content-length','0') or 0); data=self.rfile.read(length) if length else b''
        try: obj=json.loads(data.decode() or '{}')
        except Exception: obj={}
        if isinstance(obj,dict) and 'DirSize' in obj:
            target=safe_join(self.server.root,obj['DirSize']); total=0
            if target and os.path.isdir(target):
                for dp,ds,fs in os.walk(target):
                    for f in fs:
                        try: total+=os.path.getsize(os.path.join(dp,f))
                        except OSError: pass
                return self.send_basic(200,human_size(total).encode(),'text/plain; charset=utf-8')
