def validate_and_run(c):
    if not c.path:
        print(f'miniserve v{VERSION}'); log('ERROR','Refusing to start as no explicit serve path was set and no interactive terminal was attached'); log('ERROR','Please set an explicit serve path like: `miniserve /my/path`')
