    root=os.path.realpath(c.path)
    if not os.path.exists(root):
        log('ERROR','Failed to resolve path to be served'); log('ERROR','caused by: No such file or directory (os error 2)')
        print('Error: Failed to resolve path to be served',file=sys.stderr); print('caused by: No such file or directory (os error 2)',file=sys.stderr); sys.exit(1)
    if c.random_route: c.route_prefix='/'+''.join(random.choice('0123456789abcdef') for _ in range(6))
    iface=c.interfaces[-1] if c.interfaces else '0.0.0.0'
    try: srv=Server((iface,c.port),Handler)
    except OSError as e:
        print(f'miniserve v{VERSION}'); log('ERROR',f'Failed to bind server to {iface}:{c.port}'); log('ERROR',f'caused by: {e.strerror} (os error {e.errno})')
        print(f'Error: Failed to bind server to {iface}:{c.port}',file=sys.stderr); print(f'caused by: {e.strerror} (os error {e.errno})',file=sys.stderr); sys.exit(1)
    srv.config=c; srv.root=root
    if c.tls_cert and c.tls_key:
        try:
            ctx=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); ctx.load_cert_chain(c.tls_cert,c.tls_key); srv.socket=ctx.wrap_socket(srv.socket,server_side=True)
        except Exception as e: print(f'Error: Failed to set up TLS: {e}',file=sys.stderr); sys.exit(1)
    port=srv.server_address[1]; scheme='https' if c.tls_cert else 'http'
    print(f'miniserve v{VERSION}')
    if c.verbose: log('INFO','starting 20 workers')
    print(f'Bound to [::]:{port}, 0.0.0.0:{port}' if iface=='0.0.0.0' and not c.interfaces else f'Bound to {iface}:{port}')
    print(f'Serving path {root}'); print('Available at (non-exhaustive list):'); print(f'    {scheme}://127.0.0.1:{port}{c.route_prefix}')
    try:
        ip=socket.gethostbyname(socket.gethostname())
        if ip!='127.0.0.1': print(f'    {scheme}://{ip}:{port}{c.route_prefix}')
    except Exception: pass
    if iface=='0.0.0.0' and not c.interfaces: print(f'    {scheme}://[::1]:{port}{c.route_prefix}')
    print('',flush=True)
    if c.verbose: log('INFO','Actix runtime found; starting in Actix runtime'); log('INFO',f'starting service: "actix-web-service-{iface}:{port}", workers: 20, listening on: {iface}:{port}')
    try: srv.serve_forever()
    except KeyboardInterrupt: pass

